    51	        int year = date.getYear();
    52	        int dayOfMonth = date.getDayOfMonth();
    53	
    54	        if (year == 2027 && month == Month.MARCH && dayOfMonth >= 21 && dayOfMonth <= 28) {
    55	            return true;
    56	        }
    57	        if (year == 2028 && month == Month.APRIL && dayOfMonth >= 9 && dayOfMonth <= 16) {
    58	            return true;
    59	        }
    60	
    61	        return false;
    62	    }
